<?php

namespace Tests\Unit;

use PHPUnit\Framework\TestCase;

/**
 * 1.2.3 (perf-7, member design 4.3 "Main CSS shrinks by >= 60 KB"): app.scss writes out Bootstrap's
 * import stack so that (1) the responsive utility groups whose breakpoint classes no source names print their base
 * classes only (resources/sass/_bootstrap-utilities.scss, generated by scripts/css/gen_bs_utilities.py:
 * ~61 KB of .mt-xxl-5 / .order-md-last ... that nothing used) and (2) the carousel, which nothing uses, is left out.
 *
 * The generated file lists every breakpoint class it turned off. This test fails when a view or script starts using one
 * of them, or the carousel: re-run the generator then (python scripts/css/gen_bs_utilities.py, from the repository
 * root), or put the carousel back.
 */
class BootstrapUtilitiesTrimTest extends TestCase
{
    public function test_app_scss_writes_out_bootstraps_stack_with_the_trim(): void
    {
        $app = (string) file_get_contents($this->root().'/resources/sass/app.scss');

        $this->assertStringNotContainsString('@import "bootstrap/scss/bootstrap";', $app);
        $utilities = strpos($app, '@import "bootstrap/scss/utilities";');
        $trim = strpos($app, '@import "bootstrap-utilities";');
        $api = strpos($app, '@import "bootstrap/scss/utilities/api";');
        $this->assertNotFalse($utilities);
        $this->assertNotFalse($trim);
        $this->assertNotFalse($api);
        $this->assertTrue($utilities < $trim && $trim < $api, 'the trim sits between the utilities map and the API');
        $this->assertStringNotContainsString('@import "bootstrap/scss/carousel";', $app);

        // the rest of Bootstrap's stack, in its order
        $stack = ['functions', 'variables', 'variables-dark', 'maps', 'mixins', 'utilities', 'root', 'reboot', 'type', 'images',
            'containers', 'grid', 'tables', 'forms', 'buttons', 'transitions', 'dropdown', 'button-group', 'nav', 'navbar', 'card',
            'accordion', 'breadcrumb', 'pagination', 'badge', 'alert', 'progress', 'list-group', 'close', 'toasts', 'modal',
            'tooltip', 'popover', 'spinners', 'offcanvas', 'placeholders', 'helpers', 'utilities/api'];
        $at = 0;
        foreach ($stack as $part) {
            $found = strpos($app, '@import "bootstrap/scss/'.$part.'";', $at);
            $this->assertNotFalse($found, $part);
            $at = $found;
        }
    }

    public function test_no_source_uses_a_breakpoint_class_that_is_off_or_the_carousel(): void
    {
        $trim = (string) file_get_contents($this->root().'/resources/sass/_bootstrap-utilities.scss');
        preg_match_all('/^\/\/ off ([a-z-]+): (.+)$/m', $trim, $lists);
        preg_match_all('/"([a-z-]+)": map-merge\(map-get\(\$utilities, "\1"\), \(responsive: false\)\)/', $trim, $groups);
        $this->assertGreaterThanOrEqual(10, count($groups[1]));
        $this->assertSame($groups[1], $lists[1], 'every group that is off lists its classes');

        $off = [];
        foreach ($lists[2] as $classes) {
            foreach (preg_split('/\s+/', trim($classes)) ?: [] as $class) {
                $off[$class] = true;
            }
        }
        $this->assertArrayHasKey('pt-md-3', $off);
        $this->assertArrayNotHasKey('d-md-none', $off, 'display keeps its breakpoint classes (the site uses them)');

        $used = [];
        foreach ($this->sources() as $file) {
            $text = (string) file_get_contents($file);
            preg_match_all('/(?<![\w-])[a-z]+(?:-[a-z0-9]+)*-(?:sm|md|lg|xl|xxl)(?:-[a-z0-9]+)*(?![\w-])/', $text, $hits);
            foreach (array_unique($hits[0]) as $hit) {
                if (isset($off[$hit])) {
                    $used[$hit][] = substr($file, strlen($this->root()) + 1);
                }
            }
            if (preg_match('/carousel-(?:item|inner|control|indicators|caption)|data-bs-ride|data-bs-slide/', $text)) {
                $used['carousel'][] = substr($file, strlen($this->root()) + 1);
            }
        }

        ksort($used);
        $this->assertSame([], array_map(fn (array $files) => implode(', ', array_slice(array_unique($files), 0, 3)), $used),
            'Breakpoint classes the trim turned off (or the carousel) are in use: run "python scripts/css/gen_bs_utilities.py" from the repository root');
    }

    private function sources(): array
    {
        $root = $this->root();
        $files = [];
        foreach (['resources/views', 'resources/js', 'resources/admin', 'app', 'config', 'database/seeders'] as $base) {
            if (! is_dir($root.'/'.$base)) {
                continue;
            }
            $iterator = new \RecursiveIteratorIterator(new \RecursiveDirectoryIterator($root.'/'.$base, \FilesystemIterator::SKIP_DOTS));
            foreach ($iterator as $file) {
                $path = str_replace('\\', '/', $file->getPathname());
                if (preg_match('/\.(php|ts|tsx|js|vue|html)$/', $path) && ! str_contains($path, '/lang/')) {
                    $files[] = $path;
                }
            }
        }

        return $files;
    }

    private function root(): string
    {
        return str_replace('\\', '/', dirname(__DIR__, 2));
    }
}
